import pandas as pd
from sklearn.preprocessing import MinMaxScaler

def task_func(list_of_pairs):
    if list_of_pairs is None or len(list_of_pairs) == 0:
        raise Exception("The input array is empty.")

    try:
        categories, values = zip(*list_of_pairs)
    except ValueError as exc:
        raise ValueError("Each element of list_of_pairs must be a pair.") from exc

    numeric_values = pd.to_numeric(pd.Series(values), errors="raise")

    scaler = MinMaxScaler()
    normalized_values = scaler.fit_transform(numeric_values.to_numpy().reshape(-1, 1)).ravel()

    return pd.DataFrame({
        "Category": list(categories),
        "Value": normalized_values
    })
